// SPDX-License-Identifier: CC0-1.0
#include HEADER
#include "bench_clock.hpp"
#include <algorithm>
#include <cstddef>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <memory>
#include <vector>
#if FAST
using Handle = Node*;
inline Node* raw(Handle h) { return h; }
#else
using Handle = std::shared_ptr<Node>;
inline Node* raw(const Handle& h) { return h.get(); }
#endif
inline void bench_observe(const void* p) { asm volatile("" : : "g"(p) : "memory"); }
int main(int argc, char** argv) {
    if (argc != 3) return 2;
    const auto n = static_cast<std::size_t>(std::strtoull(argv[1],nullptr,10));
    const int mode = std::atoi(argv[2]);
    const auto objects = std::max<std::size_t>(1,std::min<std::size_t>(1024,131072/std::max<std::size_t>(1,n)));
    std::size_t operations = std::max<std::size_t>(1,std::min<std::size_t>(100000,2097152/std::max<std::size_t>(1,n)));
    if(mode==5) operations=std::max<std::size_t>(1,std::min<std::size_t>(32,131072/std::max<std::size_t>(1,n)));
    if(mode==6) operations=32768;
    if(mode==7) operations=objects;
    std::vector<std::size_t> indices(operations);
    std::uint64_t random=81312871;
    for(auto& x:indices){random^=random<<13;random^=random>>7;random^=random<<17;x=n?random%(n+9):0;}
    const auto construction_start=bench_stamp();
    std::vector<Handle> heads(objects);
    for(auto& h:heads){h=make_chain(n);bench_observe(raw(h));}
    const auto construction=bench_stamp()-construction_start;
    std::vector<Node*> first(objects),last(objects);
    for(std::size_t i=0;i<objects;++i){first[i]=raw(heads[i]);last[i]=raw(chain_tail(heads[i]));if(chain_size(heads[i])!=n)return 3;}
    std::vector<Handle> clones(mode==5?operations:0);
    std::uint64_t checksum=0;
    const auto operation_start=bench_stamp();
    for(std::size_t i=0;i<operations;++i){
        std::atomic_signal_fence(std::memory_order_seq_cst);
        auto& h=heads[i%objects];
        bench_observe(raw(h));
        switch(mode){
        case 0:checksum+=chain_size(h);break;
        case 1:{auto result=chain_tail(h);bench_observe(raw(result));checksum+=raw(result)!=nullptr;break;}
        case 2:{auto result=chain_nth(h,indices[i]);bench_observe(raw(result));checksum+=raw(result)!=nullptr;break;}
        case 3:h=reverse_chain(h);bench_observe(raw(h));checksum+=raw(h)!=nullptr;break;
        case 4:checksum+=has_cycle(h);break;
        case 5:clones[i]=clone_chain(h);bench_observe(raw(clones[i]));checksum+=raw(clones[i])!=nullptr;break;
        case 6:push_front_node(h);bench_observe(raw(h));checksum+=pop_front_node(h);bench_observe(raw(h));break;
        case 7:clear_chain(h);checksum+=raw(h)==nullptr;break;
        case 8:
            if(n){last[i%objects]->n=h;bench_observe(raw(h));checksum+=cycle_entry(h)==raw(h);checksum+=break_cycle(h);bench_observe(raw(h));}
            break;
        default:return 4;
        }
    }
    const auto operation=bench_stamp()-operation_start;
    std::uint64_t expected=0;
    for(std::size_t i=0;i<operations;++i){
        if(mode==0)expected+=n;
        else if(mode==1||mode==3||mode==5)expected+=n!=0;
        else if(mode==2)expected+=indices[i]<n;
        else if(mode==6||mode==7)++expected;
        else if(mode==8)expected+=2*(n!=0);
    }
    if(checksum!=expected)return 5;
    for(std::size_t i=0;i<objects;++i){
        if(chain_size(heads[i])!=(mode==7?0:n))return 6;
        if(mode==3){const auto reversals=operations/objects+(i<operations%objects);if(raw(heads[i])!=((reversals&1)?last[i]:first[i]))return 7;}
    }
    for(auto& h:clones)if(chain_size(h)!=n)return 8;
    const auto destruction_start=bench_stamp();
    std::vector<Handle>().swap(clones);
    std::vector<Handle>().swap(heads);
    const auto destruction=bench_stamp()-destruction_start;
    std::printf("%zu %zu %jd %jd %jd %jd %jd %jd %ju\n",objects,operations,static_cast<std::intmax_t>(construction.wall),static_cast<std::intmax_t>(construction.cpu),static_cast<std::intmax_t>(operation.wall),static_cast<std::intmax_t>(operation.cpu),static_cast<std::intmax_t>(destruction.wall),static_cast<std::intmax_t>(destruction.cpu),static_cast<std::uintmax_t>(checksum));
}

